#!/usr/bin/env bash
set -euo pipefail
JOB_ID=${1:?usage: workflow/02-build-summary.sh <job-id>}
ROOT=$(cd "$(dirname "$0")/.." && pwd)
DIR="$ROOT/projects/$JOB_ID"
mkdir -p "$DIR/done" "$DIR/evidence"
node - <<'NODE' "$DIR/in-process/issues.json" "$DIR/done/triage-summary.md" "$DIR/evidence/outputs.json"
const fs=require("fs");
const [issuesFile,outFile,evidenceFile]=process.argv.slice(2);
const issues=JSON.parse(fs.readFileSync(issuesFile,"utf8"));
const labels=new Map();
for(const issue of issues) for(const label of issue.labels||[]) labels.set(label.name,(labels.get(label.name)||0)+1);
let md="# Issue triage summary\n\nTotal open issues: "+issues.length+"\n\n## Labels\n";
for(const [label,count] of [...labels.entries()].sort()) md+="- "+label+": "+count+"\n";
md+="\n## Oldest issues\n";
for(const issue of issues.slice(0,10)) md+="- #"+issue.number+" "+issue.title+" ("+issue.url+")\n";
fs.writeFileSync(outFile,md);
fs.writeFileSync(evidenceFile,JSON.stringify({output:outFile,issueCount:issues.length,finishedAt:new Date().toISOString()},null,2)+"\n");
console.log(JSON.stringify({ok:true,output:outFile,issueCount:issues.length}));
NODE
